solution_type:
∀ {X Color : Type} (I : X → Color) (A Ainv B Binv : X → X),
  (∀ (x : X), @Eq.{1} X (A (Ainv x)) x) →
    (∀ (x : X), @Eq.{1} X (B (Binv x)) x) →
      @CollatzWork.Disproof.FiniteResidueFirstIntegral.IsInvariant X Color I A →
        @CollatzWork.Disproof.FiniteResidueFirstIntegral.IsInvariant X Color I B →
          (∀ (x y : X),
              @Exists.{1} Nat fun n =>
                @Eq.{1} X
                  (@CollatzWork.Disproof.FiniteResidueFirstIntegral.iterate X
                    (@CollatzWork.Disproof.FiniteResidueFirstIntegral.commutator X A Ainv B Binv) n x)
                  y) →
            ∀ (x y : X), @Eq.{1} Color (I x) (I y)

